                                {isExporting ? <LoaderCircle className="w-5 h-5 animate-spin"/> : 'ZIP으로 다운로드'}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}
        {showErrorModal && (<div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"><div className="bg-white rounded-lg shadow-xl max-w-md w-full p-6"><div className="flex justify-between items-start mb-4"><h3 className="text-xl font-bold text-gray-700">생성 실패</h3><button onClick={closeErrorModal} className="text-gray-400 hover:text-gray-500"><X className="w-5 h-5" /></button></div><p className="font-medium text-gray-600">{errorMessage}</p></div></div>)}
      </div>
    </>
  );
}

