  const processAudioWithSettings = async (file: File, duration: number) => {
    setIsProcessingAudio(true);
    setErrorMessage('');

    const fileReader = new FileReader();
    fileReader.onload = async () => {
      try {
        const dataUrl = fileReader.result as string;
        const base64Data = dataUrl.split(',')[1];
        const mimeType = file.type;

        let chunkDuration: number;
        if (chunkingMode === 'simple') {
            if (simpleChunkSize === 'short') {
                chunkDuration = duration < 60 ? 5 : duration < 180 ? 8 : 12;
            } else if (simpleChunkSize === 'long') {
                chunkDuration = duration < 60 ? 10 : duration < 180 ? 18 : 25;
            } else { // medium
                chunkDuration = duration < 60 ? 7 : duration < 180 ? 12 : 20;
            }
        } else { // detailed
            chunkDuration = detailedChunkValue;
        }

        const timeSegments = [];
        for (let i = 0; i < duration; i += chunkDuration) {
            const startTime = i;
            const endTime = Math.min(i + chunkDuration, duration);
            timeSegments.push({ startTime, endTime });
        }

        if (timeSegments.length === 0 && duration > 0) {
            timeSegments.push({ startTime: 0, endTime: duration });
        }

        const prompt = `오디오 파일을 분석하고 다음 시간 세그먼트 목록을 따르세요: ${JSON.stringify(timeSegments)}. 각 시간 세그먼트에 대해 오디오에서 일어나는 일을 설명하는 JSON 객체를 제공하세요. 각 객체는 다음을 포함해야 합니다:
- 'title': 장면에 대한 짧고 설명적인 한국어 제목.
- 'prompt': 이미지 생성 모델에 적합한, 장면의 핵심 행동, 캐릭터, 분위기를 포착하는 상세한 한국어 시각적 설명.
- 'startTime': 제공된 세그먼트의 시작 시간(초).
- 'endTime': 제공된 세그먼트의 종료 시간(초).
제공된 세그먼트 수와 정확히 일치하는 유효한 JSON 객체 배열로만 응답해 주세요.`;

        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: {
            parts: [
              {text: prompt},
              {inlineData: {data: base64Data, mimeType: mimeType}},
            ],
          },
          config: {
            responseMimeType: 'application/json',
            responseSchema: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: {type: Type.STRING},
                  prompt: {type: Type.STRING},
                  startTime: {type: Type.NUMBER},
                  endTime: {type: Type.NUMBER},
                },
                required: ['title', 'prompt', 'startTime', 'endTime'],
              },
            },
          },
        });

        const jsonStr = response.text;
        if (!jsonStr) throw new Error('모델이 장면을 생성하지 못했습니다.');

        const scenes: {
          title: string;
          prompt: string;
          startTime: number;
          endTime: number;
        }[] = JSON.parse(jsonStr);
        if (scenes.length === 0)
          throw new Error('오디오에서 장면을 추출할 수 없습니다.');

        const url = URL.createObjectURL(file);
        setAudioInfo({url, duration, name: file.name});
        setFrames(Array(scenes.length).fill(null));
        setSceneData(scenes.map((s) => ({title: s.title, prompt: s.prompt})));
        setFrameDurations(
          scenes.map((s) => Math.max(100, (s.endTime - s.startTime) * 1000)),
        ); // Ensure minimum duration
        setCurrentFrameIndex(0);
        setHistory({});
        setHistoryIndex({});
      } catch (err) {
        console.error('Error processing audio file:', err);
        setErrorMessage(
          parseError(err) || '오디오 파일을 처리하는 중 오류가 발생했습니다.',
        );
        setShowErrorModal(true);
        setAudioInfo(null);
      } finally {
        setIsProcessingAudio(false);
        setShowChunkSettingsModal(false);
        setAudioFileToProcess(null);
      }
    };
    fileReader.onerror = () => {
      setErrorMessage('파일을 읽는 데 실패했습니다.');
      setShowErrorModal(true);
      setIsProcessingAudio(false);
      setShowChunkSettingsModal(false);
      setAudioFileToProcess(null);
    };
    fileReader.readAsDataURL(file);
  }


  const handleAudioUpload = async (e: ChangeEvent<HTMLInputElement>) => {
