type AspectRatio = '16:9' | '9:16';
type ActiveTool = 'pen' | 'eraser' | 'ai-eraser' | 'pan';
type SynopsisScene = { title: string; prompt: string };
type ViewMode = 'timeline' | 'editor';

const ASPECT_RATIOS = {
  '16:9': {width: 960, height: 540},
  '9:16': {width: 540, height: 960},
};

// Helper to decode base64 string to Uint8Array
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// Helper to create a WAV blob from raw PCM data for playback
function createWavBlob(
  pcmData: Uint8Array,
  sampleRate: number,
  numChannels: number,
): Blob {
  const bitsPerSample = 16;
  const dataSize = pcmData.length;
  const buffer = new ArrayBuffer(44); // Header size
  const view = new DataView(buffer);
  const blockAlign = numChannels * (bitsPerSample / 8);
  const byteRate = sampleRate * blockAlign;

  view.setUint32(0, 0x52494646, false); // 'RIFF'
  view.setUint32(4, 36 + dataSize, true); // file-size - 8
  view.setUint32(8, 0x57415645, false); // 'WAVE'
  view.setUint32(12, 0x666d7420, false); // 'fmt '
  view.setUint32(16, 16, true); // 16 for PCM
  view.setUint16(20, 1, true); // PCM is 1
  view.setUint16(22, numChannels, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, byteRate, true);
  view.setUint16(32, blockAlign, true);
  view.setUint16(34, bitsPerSample, true);

  const dataHeaderBuffer = new ArrayBuffer(8);
  const dataHeaderView = new DataView(dataHeaderBuffer);
  dataHeaderView.setUint32(0, 0x64617461, false); // 'data'
  dataHeaderView.setUint32(4, dataSize, true); // data-size

  return new Blob([view.buffer, pcmData], {type: 'audio/wav'});
}

export default function Home() {
  const [viewMode, setViewMode] = useState<ViewMode>('timeline');
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const overlayCanvasRef = useRef<HTMLCanvasElement>(null);
  const [activeTool, setActiveTool] = useState<ActiveTool>('pen');
  const isInteracting = useRef(false);
  const lastPosition = useRef({ x: 0, y: 0 });
  const [penColor, setPenColor] = useState('#000000');
  const [penSize, setPenSize] = useState(5);
  const [eraserSize, setEraserSize] = useState(30);
  const colorInputRef = useRef(null);
  const [prompt, setPrompt] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showErrorModal, setShowErrorModal] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const [selectedModel, setSelectedModel] = useState('gemini-2.5-flash-image');

  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });

  const [frames, setFrames] = useState<(string | string[] | null)[]>([null]);
  const [subFrameIndex, setSubFrameIndex] = useState(0);
  const subFramePlaybackRef = useRef<number | null>(null);

  const [currentFrameIndex, setCurrentFrameIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [fps, setFps] = useState(8);
  const [frameDurations, setFrameDurations] = useState<number[]>([1000]);
  const [isExporting, setIsExporting] = useState(false);
  const [isExportingWebM, setIsExportingWebM] = useState(false);
  const playbackTimeoutRef = useRef<number | null>(null);

  const [audioInfo, setAudioInfo] = useState<{ url: string; duration: number; name: string; } | null>(null);
  const [isGeneratingNarration, setIsGeneratingNarration] = useState(false);
  const [isProcessingAudio, setIsProcessingAudio] = useState(false);
  const audioInputRef = useRef<HTMLInputElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null);

  const [aspectRatio, setAspectRatio] = useState<AspectRatio>('16:9');
  const [showAspectRatioConfirm, setShowAspectRatioConfirm] = useState(false);
  const [targetAspectRatio, setTargetAspectRatio] =
    useState<AspectRatio | null>(null);

  const [history, setHistory] = useState<{ [key: number]: (string | string[])[] }>({});
  const [historyIndex, setHistoryIndex] = useState<{ [key: number]: number }>(
    {},
  );

  const fileInputRef = useRef<HTMLInputElement>(null);

  const [cast, setCast] = useState<string[]>([]);
  const [selectedCharacterIndices, setSelectedCharacterIndices] = useState<number[]>([]);

  const [showExportModal, setShowExportModal] = useState(false);
  const [exportFormat, setExportFormat] = useState<'png' | 'jpg'>('png');
  const [gifQuality, setGifQuality] = useState(10);

  const [selectedStyle, setSelectedStyle] = useState<string | null>(null);

  const [showScriptModal, setShowScriptModal] = useState(false);
  const [scriptText, setScriptText] = useState('');
  const [isGeneratingSynopsis, setIsGeneratingSynopsis] = useState(false);
  const [sceneData, setSceneData] = useState<SynopsisScene[]>([]);
  const [showSettings, setShowSettings] = useState(false);

  // New state for chunking settings
  const [showChunkSettingsModal, setShowChunkSettingsModal] = useState(false);
  const [chunkingSource, setChunkingSource] = useState<'script' | 'audio' | null>(null);
  const [chunkingMode, setChunkingMode] = useState<'simple' | 'detailed'>('simple');
  const [simpleChunkSize, setSimpleChunkSize] = useState<'short' | 'medium' | 'long'>('medium');
  const [detailedChunkType, setDetailedChunkType] = useState<'time' | 'chars'>('time');
  const [detailedChunkValue, setDetailedChunkValue] = useState(10);
  const [audioFileToProcess, setAudioFileToProcess] = useState<File | null>(null);
  const [audioDuration, setAudioDuration] = useState(0); // To calculate expected frames
  const [isAnimatingFrame, setIsAnimatingFrame] = useState(-1);

  // State for the animation frame count modal
  const [showAnimateModal, setShowAnimateModal] = useState(false);
  const [animationTargetIndex, setAnimationTargetIndex] = useState(-1);
  const [animationFrameCount, setAnimationFrameCount] = useState(8);

  const currentFrameData = frames[currentFrameIndex];

  const drawCanvasContent = (canvas: HTMLCanvasElement | null, dataUrl: string | string[] | null) => {
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Always clear the canvas first
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    let imageUrl: string | null = null;
    if (Array.isArray(dataUrl)) {
      imageUrl = dataUrl[0];
    } else {
      imageUrl = dataUrl;
    }

    if (imageUrl) {
      const img = new Image();
      img.onload = () => {
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      };
      img.src = imageUrl;
    }
  };

  useEffect(() => {
    const currentFrame = frames[currentFrameIndex];
    if (subFramePlaybackRef.current) {
        clearInterval(subFramePlaybackRef.current);
        subFramePlaybackRef.current = null;
    }

    if (Array.isArray(currentFrame)) {
        let localSubIndex = 0;
        subFramePlaybackRef.current = window.setInterval(() => {
            localSubIndex = (localSubIndex + 1) % currentFrame.length;
            setSubFrameIndex(localSubIndex);
        }, 1000 / fps);
    } else {
        setSubFrameIndex(0); // Reset for single frames
    }

    return () => {
        if (subFramePlaybackRef.current) {
            clearInterval(subFramePlaybackRef.current);
        }
    };
  }, [currentFrameIndex, frames, fps]);

  // Effect to draw the image on the editor canvas when the view changes
  useEffect(() => {
    if (viewMode === 'editor') {
      const timeoutId = setTimeout(() => {
         drawCanvasContent(canvasRef.current, currentFrameData);
      }, 0);
      return () => clearTimeout(timeoutId);
    }
  }, [currentFrameIndex, viewMode, currentFrameData]);

  // Effect to update the prompt in the editor view
  useEffect(() => {
    if (viewMode === 'editor') {
      const currentScene = sceneData[currentFrameIndex];
      setPrompt(currentScene?.prompt || '');
    }
  }, [viewMode, currentFrameIndex, sceneData]);

  useEffect(() => {
    const overlayCanvas = overlayCanvasRef.current;
    if (overlayCanvas) {
      const overlayCtx = overlayCanvas.getContext('2d');
      overlayCtx?.clearRect(0, 0, overlayCanvas.width, overlayCanvas.height);
    }
  }, [activeTool]);

  // Combined Playback Logic
  useEffect(() => {
    const audioEl = audioRef.current;

    const handleTimeUpdate = () => {
      if (!audioEl) return;
      const currentTime = audioEl.currentTime;
      let cumulativeTime = 0;
      for (let i = 0; i < frameDurations.length; i++) {
        cumulativeTime += frameDurations[i] / 1000;
        if (currentTime < cumulativeTime) {
          if (currentFrameIndex !== i) {
            setCurrentFrameIndex(i);
          }
          break;
        }
      }
    };

    const playNextVisualFrame = () => {
      const nextIndex = (currentFrameIndex + 1) % frames.length;
      setCurrentFrameIndex(nextIndex);
      const nextDuration = frameDurations[nextIndex] ?? 1000;
      playbackTimeoutRef.current = window.setTimeout(playNextVisualFrame, nextDuration);
    };

    if (isPlaying) {
      if (audioEl && audioInfo) {
        audioEl.play();
        audioEl.addEventListener('timeupdate', handleTimeUpdate);
        audioEl.addEventListener('ended', () => setIsPlaying(false));
      } else {
        // Fallback to visual-only timer if no audio
        const currentDuration = frameDurations[currentFrameIndex] ?? 1000;
        playbackTimeoutRef.current = window.setTimeout(playNextVisualFrame, currentDuration);
      }
    } else {
      if (audioEl) {
        audioEl.pause();
      }
      if (playbackTimeoutRef.current) {
        clearTimeout(playbackTimeoutRef.current);
      }
    }

    return () => {
      if (audioEl) {
        audioEl.removeEventListener('timeupdate', handleTimeUpdate);
      }
      if (playbackTimeoutRef.current) {
        clearTimeout(playbackTimeoutRef.current);
      }
    };
  }, [isPlaying, audioInfo, frames.length, frameDurations, currentFrameIndex]);

  const getCoordinates = (e: React.MouseEvent | React.TouchEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();

    const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;

    const elementX = clientX - rect.left;
    const elementY = clientY - rect.top;

    const x = elementX * (canvas.width / rect.width);
    const y = elementY * (canvas.height / rect.height);

    return { x, y };
  };

  const startInteraction = (e: React.MouseEvent | React.TouchEvent) => {
    if ('touches' in e) e.preventDefault();
    if (isPlaying) setIsPlaying(false);

    isInteracting.current = true;

    if (activeTool === 'pan') {
      const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
      const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
      lastPosition.current = { x: clientX, y: clientY };
    } else {
      const { x, y } = getCoordinates(e);
      let ctx: CanvasRenderingContext2D | null | undefined;

      if (activeTool === 'ai-eraser') {
        ctx = overlayCanvasRef.current?.getContext('2d');
      } else {
        ctx = canvasRef.current?.getContext('2d');
      }

      if (!ctx) return;

      ctx.beginPath();
      ctx.moveTo(x, y);
    }
  };

  const moveInteraction = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isInteracting.current) return;
    if ('touches' in e) e.preventDefault();

    if (activeTool === 'pan') {
      const clientX = 'touches' in e ? e.touches[0].clientX : e.clientX;
      const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
      const dx = clientX - lastPosition.current.x;
      const dy = clientY - lastPosition.current.y;
      setPan({ x: pan.x + dx, y: pan.y + dy });
      lastPosition.current = { x: clientX, y: clientY };
    } else {
        const { x, y } = getCoordinates(e);
        let ctx: CanvasRenderingContext2D | null | undefined;

        if (activeTool === 'ai-eraser') {
            ctx = overlayCanvasRef.current?.getContext('2d');
            if (ctx) {
                ctx.strokeStyle = 'rgba(255, 255, 0, 0.5)';
                ctx.lineWidth = eraserSize;
                ctx.lineCap = 'round';
                ctx.globalCompositeOperation = 'source-over';
            }
        } else {
            ctx = canvasRef.current?.getContext('2d');
            if (ctx) {
                if (activeTool === 'pen') {
                    ctx.globalCompositeOperation = 'source-over';
                    ctx.lineWidth = penSize;
                    ctx.strokeStyle = penColor;
                } else { // eraser
                    ctx.globalCompositeOperation = 'destination-out';
                    ctx.lineWidth = eraserSize;
                }
                ctx.lineCap = 'round';
            }
        }

        if (!ctx) return;
        ctx.lineTo(x, y);
        ctx.stroke();
    }
  };

  const handleAiInpaint = async () => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const erasedImageData = canvas.toDataURL('image/png');

    const newFrames = [...frames];
    newFrames[currentFrameIndex] = erasedImageData;
    setFrames(newFrames);
    updateHistory(erasedImageData);

    setIsLoading(true);

    try {
        const aiPrompt = `Aspect Ratio: ${aspectRatio}. This is an inpainting request. The transparent pixels in this image should be filled in. Use the surrounding image content and style to fill the transparent area. Additionally, follow this user instruction: ${prompt || 'seamlessly blend with the background'}. CRITICAL: Do not include any text, letters, or numbers in the image.`;

        const parts = [
            { inlineData: { data: erasedImageData.split(',')[1], mimeType: 'image/png' } },
            { text: aiPrompt }
        ];

        const response = await ai.models.generateContent({
            model: selectedModel,
            contents: { parts },
            config: {
                imageConfig: {
                    aspectRatio: aspectRatio,
                },
            },
        });

        let generatedImageData: string | undefined;
        for (const part of response.candidates?.[0]?.content?.parts || []) {
            if (part.inlineData) {
                generatedImageData = part.inlineData.data;
                break;
            }
        }

        if (generatedImageData) {
            const imageUrl = `data:image/png;base64,${generatedImageData}`;
            const finalFrames = [...frames];
            finalFrames[currentFrameIndex] = imageUrl;
            setFrames(finalFrames);
            updateHistory(imageUrl);
            setPrompt('');
        } else {
            throw new Error('AI 지우개 작업에 실패했습니다. 안전 설정에 의해 차단되었을 수 있습니다.');
        }
    } catch (error) {
        console.error('AI inpainting failed:', error);
        setErrorMessage(parseError(error) || 'AI 지우개 작업 중 오류가 발생했습니다.');
        setShowErrorModal(true);
        handleUndo();
    } finally {
        setIsLoading(false);
    }
  };

  const stopInteraction = () => {
    if (!isInteracting.current) return;
    isInteracting.current = false;

    if (activeTool === 'pan') return;

    let targetCanvas: HTMLCanvasElement | null = null;
    if (activeTool === 'ai-eraser') {
      targetCanvas = overlayCanvasRef.current;
    } else {
      targetCanvas = canvasRef.current;
    }

    if (!targetCanvas) return;
    const ctx = targetCanvas.getContext('2d');
    if (ctx) ctx.closePath();

    if (activeTool === 'ai-eraser') {
        const mainCanvas = canvasRef.current;
        const overlayCanvas = overlayCanvasRef.current;
        if (!mainCanvas || !overlayCanvas) return;
        const mainCtx = mainCanvas.getContext('2d');
        const overlayCtx = overlayCanvas.getContext('2d');
        if (!mainCtx || !overlayCtx) return;

        mainCtx.globalCompositeOperation = 'destination-out';
        mainCtx.drawImage(overlayCanvas, 0, 0);
        mainCtx.globalCompositeOperation = 'source-over'; 

        overlayCtx.clearRect(0, 0, overlayCanvas.width, overlayCanvas.height);

        handleAiInpaint();
    } else {
         const dataUrl = targetCanvas.toDataURL('image/png');
         updateHistory(dataUrl);
         const newFrames = [...frames];
         newFrames[currentFrameIndex] = dataUrl;
         setFrames(newFrames);
    }
  };

  const updateHistory = (dataUrl: string | string[], replace = false) => {
    const currentIndex = historyIndex[currentFrameIndex] ?? -1;
    const currentHistory = history[currentFrameIndex] || [];
    const newHistory = replace
      ? [dataUrl]
      : [...currentHistory.slice(0, currentIndex + 1), dataUrl];

    setHistory({...history, [currentFrameIndex]: newHistory});
    setHistoryIndex({
      ...historyIndex,
      [currentFrameIndex]: newHistory.length - 1,
    });
  };

  const handleUndo = () => {
    const currentIndex = historyIndex[currentFrameIndex] ?? 0;
    if (currentIndex <= 0) return;

    const newIndex = currentIndex - 1;
    setHistoryIndex({...historyIndex, [currentFrameIndex]: newIndex});

    const dataUrl = history[currentFrameIndex][newIndex];
    const newFrames = [...frames];
    newFrames[currentFrameIndex] = dataUrl;
    setFrames(newFrames);
  };

  const handleRedo = () => {
    const currentIndex = historyIndex[currentFrameIndex] ?? -1;
    const frameHistory = history[currentFrameIndex] || [];
    if (currentIndex >= frameHistory.length - 1) return;

    const newIndex = currentIndex + 1;
    setHistoryIndex({...historyIndex, [currentFrameIndex]: newIndex});

    const dataUrl = frameHistory[newIndex];
    const newFrames = [...frames];
    newFrames[currentFrameIndex] = dataUrl;
    setFrames(newFrames);
  };

  const clearCanvas = () => {
    const newFrames = [...frames];
    newFrames[currentFrameIndex] = null;
    setFrames(newFrames);

    const newSceneData = [...sceneData];
    if (newSceneData[currentFrameIndex]) {
        newSceneData[currentFrameIndex] = { title: '', prompt: '' }; 
        setSceneData(newSceneData);
    }

    const newHistory = {...history};
    delete newHistory[currentFrameIndex];
    setHistory(newHistory);
    const newHistoryIdx = {...historyIndex};
    delete newHistoryIdx[currentFrameIndex];
    setHistoryIndex(newHistoryIdx);
  };

  const handleColorChange = (e: ChangeEvent<HTMLInputElement>) =>
    setPenColor(e.target.value);

  const openColorPicker = () =>
    (colorInputRef.current as HTMLInputElement)?.click();

  const processImageFile = (file: File) => {
    if (file && file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onloadend = () => {
            const dataUrl = reader.result as string;

            const tempCanvas = document.createElement('canvas');
            const targetDims = ASPECT_RATIOS[aspectRatio];
            tempCanvas.width = targetDims.width;
            tempCanvas.height = targetDims.height;
            const ctx = tempCanvas.getContext('2d');
            if (!ctx) return;

            const img = new Image();
            img.onload = () => {
                ctx.fillStyle = '#FFFFFF';
                ctx.fillRect(0, 0, tempCanvas.width, tempCanvas.height);
                const hRatio = tempCanvas.width / img.width;
                const vRatio = tempCanvas.height / img.height;
                const ratio = Math.min(hRatio, vRatio);
                const centerShift_x = (tempCanvas.width - img.width * ratio) / 2;
                const centerShift_y = (tempCanvas.height - img.height * ratio) / 2;
                ctx.drawImage(img, 0, 0, img.width, img.height, 
                              centerShift_x, centerShift_y, img.width * ratio, img.height * ratio);

                const finalDataUrl = tempCanvas.toDataURL('image/png');
                const newFrames = [...frames];
                newFrames[currentFrameIndex] = finalDataUrl;
                setFrames(newFrames);
                updateHistory(finalDataUrl, true);

                const newSceneData = [...sceneData];
                if (newSceneData[currentFrameIndex]) {
                    newSceneData[currentFrameIndex] = { title: '', prompt: '' };
                    setSceneData(newSceneData);
                }
            };
            img.src = dataUrl;
        };
        reader.readAsDataURL(file);
    }
  };

