      URL.revokeObjectURL(audioInfo.url);
    }
    setAudioInfo(null);
    setFrameDurations(new Array(frames.length).fill(1000));
  };

  const handleGenerateNarration = async () => {
    const validFrames = frames.flat().filter((f): f is string => f !== null);
    if (validFrames.length === 0) {
      setErrorMessage('내레이션을 생성하기 전에 이미지를 만드세요.');
      setShowErrorModal(true);
      return;
    }
    setIsGeneratingNarration(true);
    try {
      const descriptionParts: any[] = [
        { text: '내레이션 대본 작성을 위해 이미지를 설명하세요.' },
      ];
      validFrames.forEach((frame) => {
        descriptionParts.push({
          inlineData: {data: frame.split(',')[1], mimeType: 'image/png'},
        });
      });

      const descriptionResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {parts: descriptionParts},
      });
      const description = descriptionResponse.text ?? '';

      const scriptPrompt = `내레이션 대본을 한두 문장으로 작성하세요: ${description}.`;
      const scriptResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: scriptPrompt,
      });
      const script = (scriptResponse.text ?? '').trim();

      const ttsResponse = await ai.models.generateContent({
        model: 'gemini-2.5-flash-preview-tts',
        contents: [{parts: [{text: `Read this cheerfully: ${script}`}]}],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {prebuiltVoiceConfig: {voiceName: 'Kore'}},
          },
        },
      });

      const base64Audio = ttsResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) throw new Error('Audio data not found.');

      const pcmData = decode(base64Audio);
      const wavBlob = createWavBlob(pcmData, 24000, 1);
      const audioUrl = URL.createObjectURL(wavBlob);

      const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
      const arrayBuffer = await wavBlob.arrayBuffer();
      const audioBuffer = await audioContext.decodeAudioData(arrayBuffer);

      setAudioInfo({ url: audioUrl, duration: audioBuffer.duration, name: '생성된 내레이션.wav' });

    } catch (error) {
      setErrorMessage(parseError(error));
      setShowErrorModal(true);
    } finally {
      setIsGeneratingNarration(false);
    }
  };

  const handleExportGif = async () => {
    if (isExporting) return;
    const framesToExport = frames.flat().filter((frame): frame is string => frame !== null);
    if (framesToExport.length === 0) return;

    setIsExporting(true);
    try {
      const gif = new GIF({
        workers: 2,
        quality: gifQuality,
        workerScript: 'https://cdnjs.cloudflare.com/ajax/libs/gif.js/0.2.0/gif.worker.js',
        width: ASPECT_RATIOS[aspectRatio].width,
        height: ASPECT_RATIOS[aspectRatio].height,
      });

      const loadedImages = await Promise.all(framesToExport.map(url => {
        return new Promise<HTMLImageElement>((resolve, reject) => {
          const img = new Image();
          img.onload = () => resolve(img);
          img.onerror = reject;
          img.src = url;
        });
      }));

      let imageIndex = 0;
      for (let i = 0; i < frames.length; i++) {
          const f = frames[i];
          if (Array.isArray(f)) {
              const d = (frameDurations[i] || 1000) / f.length;
              for (const _ of f) { gif.addFrame(loadedImages[imageIndex++], { delay: d }); }
          } else if (f) {
              gif.addFrame(loadedImages[imageIndex++], { delay: frameDurations[i] || 1000 });
          }
      }

      gif.on('finished', (blob) => {
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = 'animation.gif';
        a.click();
        setIsExporting(false);
        setShowExportModal(false);
      });
      gif.render();
    } catch (error) {
      setErrorMessage(parseError(error));
      setIsExporting(false);
    }
  };

  const handleExportFrames = async () => {
    if (isExporting) return;
    const framesToExport = frames.flat().filter((frame): frame is string => Boolean(frame));
    if (framesToExport.length === 0) return;
    setIsExporting(true);
    try {
      const zip = new JSZip();
      for (let i = 0; i < framesToExport.length; i++) {
        zip.file(`frame_${String(i + 1).padStart(4, '0')}.${exportFormat}`, framesToExport[i].split(',')[1], {base64: true});
      }
      const blob = await zip.generateAsync({type: 'blob'});
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = `animation_frames.zip`;
      a.click();
    } finally {
      setIsExporting(false);
      setShowExportModal(false);
    }
  };

  const handleExportWebM = async () => {
    if (isExporting || isExportingWebM) return;
    const allSubFrames = frames.flat().filter((frame): frame is string => frame !== null);
    if (allSubFrames.length === 0) return;
    setIsExportingWebM(true);
    try {
      const canvas = document.createElement('canvas');
      canvas.width = ASPECT_RATIOS[aspectRatio].width;
      canvas.height = ASPECT_RATIOS[aspectRatio].height;
      const ctx = canvas.getContext('2d');
      const videoStream = canvas.captureStream();
      let finalStream = videoStream;

      const recorder = new MediaRecorder(finalStream, {mimeType: 'video/webm; codecs=vp9,opus'});
      const chunks: Blob[] = [];
      recorder.ondataavailable = (e) => chunks.push(e.data);
      recorder.onstop = () => {
        const a = document.createElement('a');
        a.href = URL.createObjectURL(new Blob(chunks, {type: 'video/webm'}));
        a.download = 'animation.webm';
        a.click();
        setIsExportingWebM(false);
        setShowExportModal(false);
      };

      const imgs = await Promise.all(allSubFrames.map(url => new Promise<HTMLImageElement>((res, rej) => {
        const i = new Image(); i.onload = () => res(i); i.onerror = rej; i.src = url;
      })));

      recorder.start();
      let idx = 0;
      for(let i = 0; i < frames.length; i++) {
        const f = frames[i]; if(!f) continue;
        const sub = Array.isArray(f) ? f : [f];
        const dur = (frameDurations[i] || 1000) / sub.length;
        for(const _ of sub) {
          ctx.fillStyle = '#FFFFFF';
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(imgs[idx++], 0, 0, canvas.width, canvas.height);
          await new Promise(r => setTimeout(r, dur));
        }
      }
      recorder.stop();
    } catch (e) {
      setErrorMessage(parseError(e));
      setIsExportingWebM(false);
    }
  };

  const handleConfirmAspectRatioChange = (newRatio: AspectRatio) => {
    setAspectRatio(newRatio);
    setFrames(Array(frames.length).fill(null));
    setHistory({});
    setHistoryIndex({});
    setCurrentFrameIndex(0);
    setShowAspectRatioConfirm(false);
  };

  const handleAspectRatioChange = (newRatio: AspectRatio) => {
    if (newRatio === aspectRatio) return;
    const hasContent = frames.some((f) => f !== null);
    if (hasContent) {
      setTargetAspectRatio(newRatio);
      setShowAspectRatioConfirm(true);
    } else {
      handleConfirmAspectRatioChange(newRatio);
    }
  };

  const handleSaveCharacter = () => {
    const f = frames[currentFrameIndex];
    if (f && typeof f === 'string') setCast([...cast, f]);
  };

  const handleSelectCharacter = (index: number) => {
    setSelectedCharacterIndices(prev => prev.includes(index) ? prev.filter(i => i !== index) : [...prev, index]);
  };

  const handleRemoveCharacter = (e: React.MouseEvent, i: number) => {
    e.stopPropagation();
    setCast(cast.filter((_, idx) => idx !== i));
    setSelectedCharacterIndices(prev => prev.filter(idx => idx !== i));
  };

  const handleAnimateFrame = async (idx: number, count: number) => {
      const src = frames[idx];
      const p = sceneData[idx]?.prompt || '';
      setShowAnimateModal(false);
      if (typeof src !== 'string') return;
      setIsAnimatingFrame(idx);
      try {
          const res = await ai.models.generateContent({
              model: selectedModel,
              contents: { parts: [{ inlineData: { data: src.split(',')[1], mimeType: 'image/png' } }, { text: `Generate ${count} frames animation for: ${p}` }] },
              config: { systemInstruction: SCENE_ANIMATION_SYSTEM_INSTRUCTION, imageConfig: { aspectRatio } }
          });
          const subs: string[] = [];
          for (const part of res.candidates?.[0]?.content?.parts || []) {
              if (part.inlineData) subs.push(`data:image/png;base64,${part.inlineData.data}`);
          }
          if (subs.length > 1) {
              setFrames(prev => { const next = [...prev]; next[idx] = subs; return next; });
              updateHistory(subs, true);
          }
      } catch (e) {
          setErrorMessage(parseError(e));
          setShowErrorModal(true);
      } finally { setIsAnimatingFrame(-1); }
  };

  useEffect(() => {
    const prevent = (e: TouchEvent) => { if (isInteracting.current && canvasRef.current?.contains(e.target as Node)) e.preventDefault(); };
    document.addEventListener('touchstart', prevent, { passive: false });
    document.addEventListener('touchmove', prevent, { passive: false });
    const handlePaste = (e: ClipboardEvent) => {
        const items = e.clipboardData?.items; if (!items) return;
        for (let i = 0; i < items.length; i++) {
            if (items[i].type.indexOf('image') !== -1) {
                const file = items[i].getAsFile(); if (file) processImageFile(file);
            }
        }
    };
    window.addEventListener('paste', handlePaste);
    return () => {
      document.removeEventListener('touchstart', prevent);
      document.removeEventListener('touchmove', prevent);
      window.removeEventListener('paste', handlePaste);
    };
  }, [processImageFile]);

  const canUndo = (historyIndex[currentFrameIndex] ?? 0) > 0;
  const canRedo = (historyIndex[currentFrameIndex] ?? -1) < (history[currentFrameIndex]?.length ?? 0) - 1;

  const currentCanvasDimensions = ASPECT_RATIOS[aspectRatio];
  const displayImage = Array.isArray(currentFrameData) ? currentFrameData[subFrameIndex] : currentFrameData;

  const renderTimelineView = () => (
    <div className="flex-grow w-full flex flex-col md:flex-row items-stretch gap-4 overflow-hidden">
        <div className="flex-grow flex flex-col items-center justify-center overflow-hidden p-4 bg-black/5 rounded-lg min-h-[30vh]">
            <div className="w-full h-full max-w-full max-h-full relative bg-white rounded-md shadow-inner flex items-center justify-center group" style={{ aspectRatio: aspectRatio.replace(':', ' / ') }}>
                <div className="absolute inset-0 bg-[conic-gradient(#ccc_25%,#eee_0_50%,#ccc_0_75%,#eee_0)] bg-[length:20px_20px] rounded-md z-10"></div>
                {displayImage ? ( <img src={displayImage} alt="Frame" className="absolute inset-0 w-full h-full object-contain z-20" /> ) : ( <div className="relative z-20 text-center p-4"> <h2 className="text-lg font-bold text-gray-500">빈 프레임</h2> </div> )}
