/* tslint:disable */
import React, {ChangeEvent, useEffect, useRef, useState, useCallback} from 'react';
import {GoogleGenAI, Modality, Type} from '@google/genai';
import GIF from 'gif.js';
import JSZip from 'jszip';
import {
  ArrowLeft,
  BarChart4,
  Bot,
  Box,
  Brush,
  ChevronDown,
  Download,
  Eraser,
  Feather,
  FileText,
  Film,
  Grid3X3,
  Hand,
  Laugh,
  LoaderCircle,
  MousePointerClick,
  Music2,
  Palette,
  Pause,
