      for (const part of res.candidates?.[0]?.content?.parts || []) { if (part.inlineData) subs.push(`data:image/png;base64,${part.inlineData.data}`); }
      if (subs.length > 1) {
        setFrames(prev => { const next = [...prev]; next[idx] = subs; return next; });
