          <div className="mt-3 pt-3 border-t space-y-3">
            <div className="flex items-center gap-2"><span className="text-[10px] font-bold">FPS</span><input type="range" min="1" max="24" value={fps} onChange={e => setFps(Number(e.target.value))} className="flex-grow"/><span className="text-[10px] w-4">{fps}</span></div>
            <div className="flex justify-between items-center"><div className="flex items-center gap-1"><span className="text-[10px]">시간:</span><input type="number" step="0.1" value={(frameDurations[currentFrameIndex] || 1000)/1000} onChange={e => { const v = Number(e.target.value); if(v>0){ const n = [...frameDurations]; n[currentFrameIndex] = v*1000; setFrameDurations(n); } }} className="w-10 text-[10px] border rounded p-0.5 text-center"/></div><button onClick={handleGenerateNarration} disabled={isGeneratingNarration} className="p-2 bg-white shadow rounded-full hover:scale-110 disabled:opacity-50">{isGeneratingNarration ? <LoaderCircle className="w-4 h-4 animate-spin"/> : <Sparkles className="w-4 h-4 text-blue-500"/>}</button></div>
